-- rule truncated_third (row): parameterized; p1 text, p2 text, p3 numeric, p4 numeric
SELECT t."parent_id", t."child_id", t."qty_per", count(*) AS "n" FROM "sxc_rules"."bom_line" t WHERE (EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE n."part_id" = t."child_id" AND (n."unit" IS NOT NULL AND n."unit" IN (CAST(:p1 AS text), CAST(:p2 AS text))))) AND (t."qty_per" IS NOT NULL AND t."qty_per" IN (CAST(:p3 AS numeric), CAST(:p4 AS numeric))) GROUP BY t."parent_id", t."child_id", t."qty_per";

-- rule truncated_third: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_truncated_third" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST, r."child_id" COLLATE "C" NULLS FIRST, r."qty_per" NULLS FIRST, r."n" NULLS FIRST) AS ord FROM (SELECT t."parent_id", t."child_id", t."qty_per", count(*) AS "n" FROM "sxc_rules"."bom_line" t WHERE (EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE n."part_id" = t."child_id" AND (n."unit" IS NOT NULL AND n."unit" IN (CAST(E'pc' AS text), CAST(E'box' AS text))))) AND (t."qty_per" IS NOT NULL AND t."qty_per" IN (CAST(E'0.3333' AS numeric), CAST(E'0.6666' AS numeric))) GROUP BY t."parent_id", t."child_id", t."qty_per") r;

-- example truncated_third[0]: parameterized; 17 parameters
WITH "sxc_ex_bom_line"("child_id", "qty_per", "parent_id") AS (VALUES (CAST(:p1 AS text), CAST(:p2 AS numeric(18,6)), CAST(:p3 AS text)), (CAST(:p4 AS text), CAST(:p5 AS numeric(18,6)), CAST(:p6 AS text)), (CAST(:p7 AS text), CAST(:p8 AS numeric(18,6)), CAST(:p9 AS text))), "sxc_ex_part"("part_id", "unit") AS (VALUES (CAST(:p10 AS text), CAST(:p11 AS text)), (CAST(:p12 AS text), CAST(:p13 AS text))) SELECT * FROM (SELECT t."parent_id", t."child_id", t."qty_per", count(*) AS "n" FROM "sxc_ex_bom_line" t WHERE (EXISTS (SELECT 1 FROM "sxc_ex_part" n WHERE n."part_id" = t."child_id" AND (n."unit" IS NOT NULL AND n."unit" IN (CAST(:p14 AS text), CAST(:p15 AS text))))) AND (t."qty_per" IS NOT NULL AND t."qty_per" IN (CAST(:p16 AS numeric), CAST(:p17 AS numeric))) GROUP BY t."parent_id", t."child_id", t."qty_per") r;
